-- Refresh the subscription_renewal email template to include an explicit
-- "Cancel Subscription" entry alongside the existing "Manage Subscription" CTA.
-- The wrapper function SendSubscriptionRenewalEmail (server/utils/email_template.go)
-- supplies {{dashboardUrl}} so both links resolve to the user's billing dashboard.

UPDATE `w_email_template`
SET `content` = '<!DOCTYPE html>\n<html>\n<head>\n    <meta charset="UTF-8">\n    <title>Subscription Renewed - WorkMax</title>\n</head>\n<body style="margin:0;padding:0;font-family:Arial,sans-serif;background:#f9fafb;">\n    <div style="max-width:600px;margin:0 auto;background:#fff;box-shadow:0 4px 6px rgba(0,0,0,0.05);">\n        <div style="background:#2563eb;padding:60px 48px;text-align:center;">\n            <h1 style="margin:0;color:#fff;font-size:28px;font-weight:700;">Subscription Renewed</h1>\n            <p style="margin:8px 0 0;color:rgba(255,255,255,0.9);font-size:16px;">WorkMax Pro Access Continued</p>\n        </div>\n        <div style="padding:48px;">\n            <p style="font-size:16px;color:#374151;margin:0 0 12px;line-height:1.6;">Hi {{nickname}},</p>\n            <p style="font-size:15px;color:#6b7280;margin:0 0 40px;line-height:1.8;">Your WorkMax subscription has been successfully renewed. Thank you for continuing your creative journey with us!</p>\n\n            <div style="background:#dbeafe;border:2px solid #2563eb;padding:24px;border-radius:12px;text-align:center;margin:40px 0;">\n                <p style="margin:0;font-size:18px;color:#2563eb;font-weight:700;">Your premium access is active and ready to use</p>\n            </div>\n\n            <table style="width:100%;border-collapse:collapse;border:1px solid #e5e7eb;border-radius:12px;overflow:hidden;margin:40px 0;">\n                <tr>\n                    <td style="padding:20px;font-size:15px;color:#6b7280;border-bottom:1px solid #e5e7eb;background:#f9fafb;font-weight:600;">Plan</td>\n                    <td style="padding:20px;font-size:15px;color:#111827;text-align:right;border-bottom:1px solid #e5e7eb;background:#f9fafb;font-weight:700;">{{planName}}</td>\n                </tr>\n                <tr>\n                    <td style="padding:20px;font-size:15px;color:#6b7280;border-bottom:1px solid #e5e7eb;">Next Billing Date</td>\n                    <td style="padding:20px;font-size:15px;color:#111827;text-align:right;border-bottom:1px solid #e5e7eb;">{{renewalDate}}</td>\n                </tr>\n                <tr>\n                    <td style="padding:20px;font-size:15px;color:#6b7280;border-bottom:1px solid #e5e7eb;">Payment Method</td>\n                    <td style="padding:20px;font-size:15px;color:#111827;text-align:right;border-bottom:1px solid #e5e7eb;">{{paymentMethod}}</td>\n                </tr>\n                <tr style="background:#f9fafb;">\n                    <td style="padding:20px;font-size:16px;color:#374151;font-weight:700;border-top:2px solid #d1d5db;">Amount</td>\n                    <td style="padding:20px;font-size:24px;color:#2563eb;font-weight:800;text-align:right;border-top:2px solid #d1d5db;">{{amount}}</td>\n                </tr>\n            </table>\n\n            <div style="text-align:center;margin:48px 0 16px;">\n                <a href="{{dashboardUrl}}/dashboard/order" style="display:inline-block;background:#2563eb;color:#fff;padding:18px 48px;text-decoration:none;border-radius:12px;font-weight:700;font-size:16px;margin:0 6px 12px;">Manage Subscription</a>\n                <a href="{{dashboardUrl}}/dashboard/order?action=cancel" style="display:inline-block;background:#fff;color:#2563eb;padding:17px 40px;text-decoration:none;border-radius:12px;font-weight:700;font-size:16px;border:2px solid #2563eb;margin:0 6px 12px;">Cancel Subscription</a>\n            </div>\n            <p style="font-size:13px;color:#9ca3af;text-align:center;line-height:1.7;margin:0;">Need to stop future renewals? Click "Cancel Subscription" above, or visit <a href="{{dashboardUrl}}/dashboard/order" style="color:#2563eb;text-decoration:none;">your billing dashboard</a> at any time.</p>\n        </div>\n        <div style="padding:32px 48px;text-align:center;background:#f9fafb;border-top:1px solid #e5e7eb;">\n            <p style="margin:0;font-size:13px;color:#9ca3af;">&copy; 2026 WorkMax &middot; AI Video Production Platform</p>\n            <p style="margin:8px 0 0;font-size:12px;color:#9ca3af;">Automated Billing Notification</p>\n        </div>\n    </div>\n</body>\n</html>',
    `updated_at` = NOW()
WHERE `code` = 'subscription_renewal';
